Hi @agardiol, Coverity found the following issue in your change:

```
*** CID 1495425:  Integer handling issues  (CONSTANT_EXPRESSION_RESULT)
/builds/wireshark/wireshark/epan/dissectors/packet-5co-legacy.c: 765 in fiveco_hash()
759     /*****************************************************************************/
760     static guint fiveco_hash(gconstpointer v)
761     {
762         const FCOSConvRequestKey *key = (const FCOSConvRequestKey *)v;
763         guint val;
764     
>>>     CID 1495425:  Integer handling issues  (CONSTANT_EXPRESSION_RESULT)
>>>     "(key->usExpCmd << 16) & 0xffff" is always 0 regardless of the values of its operands. This occurs as a value.
765         val = key->conversation + (((key->usExpCmd) << 16) & 0xFFFF) +
766                 (key->unInternalID & 0xFFFFFFFF) + ((key->unInternalID >>32) & 0xFFFFFFFF);
767     
768         return val;
769     }
```
